CREATE TABLE BANK_USERS(USER_ID NUMBER PRIMARY KEY,USERNAME VARCHAR2(50) UNIQUE NOT NULL,USER_PASSWORD VARCHAR2(100) NOT NULL,FULL_NAME VARCHAR2(100),STATUS VARCHAR2(20) DEFAULT 'ACTIVE');
CREATE TABLE BANK_CUSTOMERS(CUSTOMER_ID NUMBER PRIMARY KEY,CUSTOMER_NAME VARCHAR2(100) NOT NULL,PHONE VARCHAR2(20),EMAIL VARCHAR2(100),ADDRESS VARCHAR2(200));
CREATE TABLE BANK_ACCOUNTS(ACCOUNT_ID NUMBER PRIMARY KEY,CUSTOMER_ID NUMBER NOT NULL,ACCOUNT_NUMBER VARCHAR2(30) UNIQUE NOT NULL,ACCOUNT_TYPE VARCHAR2(30) NOT NULL,BALANCE NUMBER(15,2) DEFAULT 0 NOT NULL,OPEN_DATE DATE DEFAULT SYSDATE,STATUS VARCHAR2(20) DEFAULT 'ACTIVE',CONSTRAINT FK_BA_C FOREIGN KEY(CUSTOMER_ID) REFERENCES BANK_CUSTOMERS(CUSTOMER_ID));
CREATE TABLE BANK_TRANSACTIONS(TRANSACTION_ID NUMBER PRIMARY KEY,ACCOUNT_ID NUMBER NOT NULL,TRANSACTION_TYPE VARCHAR2(30) NOT NULL,AMOUNT NUMBER(15,2) NOT NULL,TRANSACTION_DATE DATE DEFAULT SYSDATE,DESCRIPTION VARCHAR2(200),CONSTRAINT FK_BT_A FOREIGN KEY(ACCOUNT_ID) REFERENCES BANK_ACCOUNTS(ACCOUNT_ID));
CREATE TABLE BANK_TRANSFERS(TRANSFER_ID NUMBER PRIMARY KEY,FROM_ACCOUNT_ID NUMBER NOT NULL,TO_ACCOUNT_ID NUMBER NOT NULL,AMOUNT NUMBER(15,2) NOT NULL,TRANSFER_DATE DATE DEFAULT SYSDATE,DESCRIPTION VARCHAR2(200),CONSTRAINT FK_BTR_F FOREIGN KEY(FROM_ACCOUNT_ID) REFERENCES BANK_ACCOUNTS(ACCOUNT_ID),CONSTRAINT FK_BTR_T FOREIGN KEY(TO_ACCOUNT_ID) REFERENCES BANK_ACCOUNTS(ACCOUNT_ID));
CREATE SEQUENCE BANK_USER_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE BANK_CUSTOMER_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE BANK_ACCOUNT_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE BANK_TRANSACTION_SEQ START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE BANK_TRANSFER_SEQ START WITH 1 INCREMENT BY 1;
